export const HM_SCHEMA_PAGES: Record<string, {name: string; summary?: string}> = {"blob":{"name":"Blob","summary":"The signed base envelope every Hypermedia CBOR blob extends: a `type` tag (the discriminator the network dispatches on), the signer's public key, an Ed25519 sig"},"block":{"name":"Block","summary":"The open block: the common fields (id, type, text, link, annotations, attributes) plus arbitrary extra fields of any type, requiring only id and type. This is t"},"capability":{"name":"Capability","summary":"A delegation granting a role (WRITER or AGENT) from a space owner (the signer) to a delegate key, optionally scoped to a path."},"change":{"name":"Change","summary":"An append-only change to a document, linked into a causal DAG via deps. Carries the operations that mutate document content and metadata."},"cid":{"name":"CID","summary":"A content identifier: a link (CBOR tag 42) referencing another IPFS block by its hash."},"comment":{"name":"Comment","summary":"A comment on a document version, threaded via threadRoot and replyParent. Its body is a tree of comment blocks."},"contact":{"name":"Contact","summary":"A contact record: one account's named reference to another account (the subject), with subscription preferences."},"document":{"name":"Document","summary":"The base Hypermedia document — resolved metadata (including the schema-binding fields `schema`, `childrenSchema`, `schemaDefinition`) plus the content block tre"},"example/address":{"name":"Example: Address","summary":"A postal address: street and city (required) plus an optional postal code."},"example/admin":{"name":"Example: Admin","summary":"An employee, extended with a list of permissions."},"example/alice":{"name":"Example: Alice","summary":"example/alice — instance."},"example/app-block":{"name":"Example: App Block (Extended Core)","summary":"How a third party extends the block model: the union of Hypermedia's core blocks PLUS their own custom blocks (here, a Poll). Strict — it accepts core blocks an"},"example/article":{"name":"Example: Article","summary":"A published article: status, author, tags, a bytes body, cover image, comments, and metadata."},"example/blob":{"name":"Example: Blob","summary":"A binary payload tagged with a MIME type and optional size."},"example/bob":{"name":"Example: Bob","summary":"example/bob — instance."},"example/carol":{"name":"Example: Carol","summary":"example/carol — instance."},"example/character-doc":{"name":"Character","summary":"A world-builder kit type: a page about a character. Extends the base document; its metadata requires a `born` date and a `role`, and links the character to a ho"},"example/comment":{"name":"Example: Comment","summary":"A comment with an author and replies, which are themselves comments."},"example/constrained":{"name":"Example: Constrained Record","summary":"Exercises the value constraints: string length + pattern, numeric bounds, and list size."},"example/counts":{"name":"Example: Counts","summary":"example/counts — an example schema."},"example/dave":{"name":"Example: Dave","summary":"example/dave — instance."},"example/document":{"name":"Example: Document","summary":"example/document — an example schema."},"example/employee":{"name":"Example: Employee","summary":"A person, extended with an employee id and department."},"example/entry":{"name":"Example: Filesystem Entry","summary":"Either a folder or a file (a union)."},"example/event-doc":{"name":"Event","summary":"A world-builder kit type: a page about something that happened. Requires a `date` and links the event to a location (a Place), a protagonist (a Character), and "},"example/faction-doc":{"name":"Faction","summary":"A world-builder kit type: a page about a faction, order, house, or guild. Requires a `founded` date; links to its seat (a Place) and leader (a Character), and a"},"example/file":{"name":"Example: File","summary":"example/file — an example schema."},"example/folder":{"name":"Example: Folder","summary":"example/folder — an example schema."},"example/geo":{"name":"Example: Geo Point","summary":"A latitude/longitude coordinate with an optional altitude."},"example/json":{"name":"Example: JSON Value","summary":"A recursive JSON value: null, boolean, number, string, list, or map. References itself."},"example/matrix":{"name":"Example: Matrix","summary":"A list of lists of integers — List<List<Integer>>."},"example/metadata":{"name":"Example: Metadata","summary":"Arbitrary string-to-string metadata — Map<String>."},"example/myapp-change":{"name":"Example: MyApp Change","summary":"A Change instantiated with this app's block type — Change<example/app-block>. Because Block is bound, its ReplaceBlock ops are validated strictly against the ap"},"example/person-doc":{"name":"Example: Person Document","summary":"A document that describes a person — the base document, refined so its metadata requires a `surname`. Illustrates the corrected model: a typed document schema e"},"example/person":{"name":"Example: Person","summary":"A person with a name, age, active flag, home address, and nicknames."},"example/place-doc":{"name":"Place","summary":"A world-builder kit type: a page about a place. Its metadata requires a `kind`, may carry a `founded` date, nests inside a `region` (another Place), and links t"},"example/poll-block":{"name":"Example: Poll Block (Custom)","summary":"An example third-party block type: a poll with a question and options. It extends the shared block base, exactly like a core block."},"example/registry":{"name":"Example: Registry","summary":"A map from ids to person links — Map<Link<Person>>."},"example/root":{"name":"Example: Root","summary":"example/root — instance."},"example/stats":{"name":"Character Stats","summary":"A character's attribute block — the object a character page links to from its `stats` field. Lives as its own DAG-CBOR blob (an `ipfs://` reference), so it can "},"example/status":{"name":"Example: Status","summary":"A publication status: draft, published, or archived."},"example/tags":{"name":"Example: Tags","summary":"A list of string tags — List<String>."},"example/tree":{"name":"Example: Tree","summary":"A node holding an integer value and links to child nodes."},"example/value":{"name":"Example: Value","summary":"A primitive value: string, integer, boolean, or null."},"example/world-doc":{"name":"World","summary":"A world-builder kit type: the root page of a fictional world. Its children are the type definitions and the folders of characters, places, factions, and events;"},"hm-url":{"name":"Resource URL","summary":"A reference to a Hypermedia document, held as an `hm://` URL string. `format: hm-url` tells an editor to render it as a searchable reference that displays the t"},"ipfs-url":{"name":"IPFS URL","summary":"A reference to a content-addressed file on IPFS, held as an `ipfs://<cid>` string. `format: ipfs-url` tells an editor to render it as a file reference — a pill you "},"metadata":{"name":"Document Metadata","summary":"Resolved document metadata (merged from Change ops): known keys plus arbitrary extras."},"principal":{"name":"Principal","summary":"A public key identifying an account, agent, or space — raw CBOR bytes (a packed multicodec key)."},"profile":{"name":"Profile","summary":"A snapshot describing an account: display name, avatar, and description — or an alias redirecting to another key."},"ref":{"name":"Ref","summary":"A signed pointer (like a Git ref) claiming that a path in a space points at the current head Changes of a document."},"role":{"name":"Role","summary":"A capability role: WRITER (edit a document) or AGENT (act on behalf of an account)."},"rpc/account-contacts":{"name":"RPC: AccountContacts","summary":"Lists the contacts an account has named. One method of the Seed universal-client API: `request(key, input) -> output`. The `input` field types what you pass; `o"},"rpc/account":{"name":"RPC: Account","summary":"Resolves an account by uid. One method of the Seed universal-client API: `request(key, input) -> output`. The `input` field types what you pass; `output` types "},"rpc/comment":{"name":"RPC: Comment","summary":"Fetches one comment by id or version CID. One method of the Seed universal-client API: `request(key, input) -> output`. The `input` field types what you pass; `"},"rpc/discovery-status":{"name":"RPC: DiscoveryStatus","summary":"Reports the state of a background discovery task. One method of the Seed universal-client API: `request(key, input) -> output`. The `input` field types what you"},"rpc/get-cid":{"name":"RPC: GetCID","summary":"Fetches a raw IPFS block by CID and decodes it. One method of the Seed universal-client API: `request(key, input) -> output`. The `input` field types what you p"},"rpc/get-comment-reply-count":{"name":"RPC: GetCommentReplyCount","summary":"Counts the replies under a comment. One method of the Seed universal-client API: `request(key, input) -> output`. The `input` field types what you pass; `output"},"rpc/get-domain":{"name":"RPC: GetDomain","summary":"Checks a site domain's registration and health. One method of the Seed universal-client API: `request(key, input) -> output`. The `input` field types what you p"},"rpc/interaction-summary":{"name":"RPC: InteractionSummary","summary":"Aggregates interaction counts for a document, per block included. One method of the Seed universal-client API: `request(key, input) -> output`. The `input` fiel"},"rpc/list-accounts":{"name":"RPC: ListAccounts","summary":"Lists all known accounts as metadata payloads. One method of the Seed universal-client API: `request(key, input) -> output`. The `input` field types what you pa"},"rpc/list-capabilities":{"name":"RPC: ListCapabilities","summary":"Lists raw capabilities granted on a target. One method of the Seed universal-client API: `request(key, input) -> output`. The `input` field types what you pass;"},"rpc/list-changes":{"name":"RPC: ListChanges","summary":"Lists a document's change history. One method of the Seed universal-client API: `request(key, input) -> output`. The `input` field types what you pass; `output`"},"rpc/list-citations":{"name":"RPC: ListCitations","summary":"Lists raw citations of a target resource. One method of the Seed universal-client API: `request(key, input) -> output`. The `input` field types what you pass; `"},"rpc/list-comment-versions":{"name":"RPC: ListCommentVersions","summary":"Lists the edit history (all versions) of a comment. One method of the Seed universal-client API: `request(key, input) -> output`. The `input` field types what y"},"rpc/list-comments-by-author":{"name":"RPC: ListCommentsByAuthor","summary":"Lists the comments an author has written. One method of the Seed universal-client API: `request(key, input) -> output`. The `input` field types what you pass; `"},"rpc/list-comments-by-reference":{"name":"RPC: ListCommentsByReference","summary":"Lists comments that reference a specific block (the target id carries the blockRef). One method of the Seed universal-client API: `request(key, input) -> output"},"rpc/list-comments":{"name":"RPC: ListComments","summary":"Lists all comments on a target document. One method of the Seed universal-client API: `request(key, input) -> output`. The `input` field types what you pass; `o"},"rpc/list-discussions":{"name":"RPC: ListDiscussions","summary":"Lists threaded discussions on a document (optionally focused on one comment), plus citing discussions from other documents. One method of the Seed universal-cli"},"rpc/list-document-collaborators":{"name":"RPC: ListDocumentCollaborators","summary":"Resolves a document's full collaboration picture. One method of the Seed universal-client API: `request(key, input) -> output`. The `input` field types what you"},"rpc/list-domains":{"name":"RPC: ListDomains","summary":"Lists all site domains the daemon knows about. One method of the Seed universal-client API: `request(key, input) -> output`. The `input` field types what you pa"},"rpc/list-events":{"name":"RPC: ListEvents","summary":"Pages through the activity feed, with author/type/resource filters. One method of the Seed universal-client API: `request(key, input) -> output`. The `input` fi"},"rpc/method":{"name":"RPC","summary":"The union of every read-only method of the Seed universal-client API. Each variant pins a method key and types its input and output — the machine-readable catal"},"rpc/query-block":{"name":"RPC: QueryBlock","summary":"Runs a Query block's query and returns everything its rendering needs. One method of the Seed universal-client API: `request(key, input) -> output`. The `input`"},"rpc/query":{"name":"RPC: Query","summary":"Runs a document query (the same shape a Query block embeds). One method of the Seed universal-client API: `request(key, input) -> output`. The `input` field typ"},"rpc/resource-metadata":{"name":"RPC: ResourceMetadata","summary":"Fetches only a resource's metadata payload. One method of the Seed universal-client API: `request(key, input) -> output`. The `input` field types what you pass;"},"rpc/resource":{"name":"RPC: Resource","summary":"Fetches a resource (document, comment, redirect, …) by parsed id. One method of the Seed universal-client API: `request(key, input) -> output`. The `input` fiel"},"rpc/search":{"name":"RPC: Search","summary":"Searches the network for documents, contacts, and comments. One method of the Seed universal-client API: `request(key, input) -> output`. The `input` field type"},"rpc/subject-contacts":{"name":"RPC: SubjectContacts","summary":"Lists the contact records that name a subject. One method of the Seed universal-client API: `request(key, input) -> output`. The `input` field types what you pa"},"rpc/type/account-result":{"name":"Account Result","summary":"The result of resolving an account: its metadata payload, or an explicit not-found. A derived read model computed by the Seed daemon/API for clients — not a sig"},"rpc/type/accounts-metadata":{"name":"Accounts Metadata","summary":"Account uid -> resolved metadata payload, sent alongside listings so clients can render authors without extra requests. A derived read model computed by the See"},"rpc/type/activity-event":{"name":"Activity Event","summary":"One event of the activity feed. The event union is not yet pinned down schema-side, so this is an open map — tightening it is tracked follow-up work. A derived "},"rpc/type/activity-summary":{"name":"Activity Summary","summary":"Latest-activity digest carried on document listings: newest comment/change and unread state. A derived read model computed by the Seed daemon/API for clients — "},"rpc/type/block-range":{"name":"Block Range","summary":"A selection within a block: either character offsets (start/end) or the whole block expanded. A derived read model computed by the Seed daemon/API for clients —"},"rpc/type/breadcrumb":{"name":"Breadcrumb","summary":"One ancestor entry of a document's path, resolved to a display name. A derived read model computed by the Seed daemon/API for clients — not a signed network blo"},"rpc/type/capability":{"name":"Capability (Payload)","summary":"A capability as the API returns it: who was granted which role on which grant id. A derived read model computed by the Seed daemon/API for clients — not a signe"},"rpc/type/citation":{"name":"Citation","summary":"One mention of a target resource from elsewhere on the network: the citing source (a document 'd' or a comment 'c'), whether it pinned the exact version, and th"},"rpc/type/collaborators-payload":{"name":"Collaborators Payload","summary":"A document's collaboration picture: the publisher, inherited and directly granted capabilities, effective members, and their metadata. A derived read model comp"},"rpc/type/comment-group":{"name":"Comment Group","summary":"A thread of comments grouped for display, with a count of elided replies. A derived read model computed by the Seed daemon/API for clients — not a signed networ"},"rpc/type/comment-list":{"name":"Comment List","summary":"A list of comments plus the metadata payloads of every author involved. A derived read model computed by the Seed daemon/API for clients — not a signed network "},"rpc/type/comment":{"name":"Comment (Payload)","summary":"A comment as the API returns it to clients: the signed comment's content plus derived fields (stable id, version CID, thread links, timestamps, visibility). A d"},"rpc/type/contact-record":{"name":"Contact Record","summary":"A contact as the API returns it: who named whom what, signed by which key, with timestamps and subscription preferences. A derived read model computed by the Se"},"rpc/type/discovery-status":{"name":"Discovery Status","summary":"The state of a background discovery task for a resource: pending, found (with the resolved version), or failed (with the error). A derived read model computed b"},"rpc/type/document-info":{"name":"Document Info","summary":"One document in a listing (query results, directories): identity, authorship, timestamps, breadcrumbs, and its activity summary — without the full content. A de"},"rpc/type/document":{"name":"Document (Payload)","summary":"A document as the API returns it to clients: the signed document's metadata and content plus derived fields (resolved version, authors, timestamps, visibility)."},"rpc/type/domain-info":{"name":"Domain Info","summary":"The daemon's view of a site domain: registration, gateway status, and health-check results. A derived read model computed by the Seed daemon/API for clients — n"},"rpc/type/external-comment-group":{"name":"External Comment Group","summary":"A comment thread from ANOTHER document that cites this one, with its target's metadata payload. A derived read model computed by the Seed daemon/API for clients"},"rpc/type/id":{"name":"Parsed ID","summary":"A parsed hm:// identifier as clients pass it around: account uid, path segments, pinned version, block reference, and origin hints. Fields the URL does not carr"},"rpc/type/interaction-summary":{"name":"Interaction Summary","summary":"Aggregate interaction counts for a document — citations, comments, changes, child documents, distinct authors — plus per-block citation/comment counts. A derive"},"rpc/type/metadata-payload":{"name":"Metadata Payload","summary":"A resource id with its resolved metadata (null when the document has none). A derived read model computed by the Seed daemon/API for clients — not a signed netw"},"rpc/type/parsed-fragment":{"name":"Parsed Fragment","summary":"A parsed URL fragment addressing a block (and optionally a range inside it). A derived read model computed by the Seed daemon/API for clients — not a signed net"},"rpc/type/query-block-item-summary":{"name":"Query Block Item Summary","summary":"Per-result interaction counts a Query block shows on its cards. A derived read model computed by the Seed daemon/API for clients — not a signed network blob."},"rpc/type/query-block-payload":{"name":"Query Block Payload","summary":"Everything a rendered Query block needs: the results plus per-item interaction summaries and author metadata. A derived read model computed by the Seed daemon/A"},"rpc/type/query-result":{"name":"Query Result","summary":"The documents a query matched, listed under the queried id. A derived read model computed by the Seed daemon/API for clients — not a signed network blob."},"rpc/type/raw-capability":{"name":"Raw Capability","summary":"A capability as indexed, in raw wire form (all fields optional strings). A derived read model computed by the Seed daemon/API for clients — not a signed network"},"rpc/type/raw-citation":{"name":"Raw Citation","summary":"A citation in raw indexed form, before client-side resolution into a rpc/type/citation. A derived read model computed by the Seed daemon/API for clients — not a sig"},"rpc/type/raw-document-change":{"name":"Raw Document Change","summary":"One change of a document's history in raw listing form: CID, author, dependency edges, time. A derived read model computed by the Seed daemon/API for clients — "},"rpc/type/redirect-info":{"name":"Redirect Info","summary":"Marks a listed document as a redirect to another target. A derived read model computed by the Seed daemon/API for clients — not a signed network blob."},"rpc/type/resource-comment":{"name":"Resource: Comment","summary":"A resolved resource that is a comment. A derived read model computed by the Seed daemon/API for clients — not a signed network blob."},"rpc/type/resource-document":{"name":"Resource: Document","summary":"A resolved resource that is a document. A derived read model computed by the Seed daemon/API for clients — not a signed network blob."},"rpc/type/resource-error":{"name":"Resource: Error","summary":"A resource that failed to load, with the error message. A derived read model computed by the Seed daemon/API for clients — not a signed network blob."},"rpc/type/resource-not-found":{"name":"Resource: Not Found","summary":"A resource id that resolved to nothing. A derived read model computed by the Seed daemon/API for clients — not a signed network blob."},"rpc/type/resource-redirect":{"name":"Resource: Redirect","summary":"A resource that redirects to another id (optionally republishing its content in place). A derived read model computed by the Seed daemon/API for clients — not a"},"rpc/type/resource-tombstone":{"name":"Resource: Tombstone","summary":"A resource that was deleted (a tombstone ref). A derived read model computed by the Seed daemon/API for clients — not a signed network blob."},"rpc/type/resource":{"name":"Resource","summary":"The union of every state a fetched resource can be in: a document, a comment, a redirect, not found, a tombstone, or an error. A derived read model computed by "},"rpc/type/search-result-item":{"name":"Search Result Item","summary":"One hit of a network search: the matched id with display info (title, icon, breadcrumb parent names) and what kind of entity matched. A derived read model compu"},"rpc/type/search-results":{"name":"Search Results","summary":"A page of search results with the query echoed back and a pagination token. A derived read model computed by the Seed daemon/API for clients — not a signed netw"},"rpc/type/site-member":{"name":"Site Member","summary":"One member of a site with their effective role. A derived read model computed by the Seed daemon/API for clients — not a signed network blob."},"schema":{"name":"Schema","summary":"The meta-schema: a discriminated union of the shapes a schema can take, and a valid instance of itself — how to browse, author and validate schemas in the Seed app, plus the full reference documentation."},"schema/any-blob":{"name":"Any Blob","summary":"Any Hypermedia CBOR blob — the discriminated union of the six blob types, tagged on the type field."},"schema/any":{"name":"Any","summary":"The top type — matches any Hypermedia value: null, boolean, number, string, bytes, link, or a (recursively any) list or map. Use it for open, forward-compatible data."},"schema/anyof":{"name":"Union schema","summary":"The variant for a union — a value matching any one of several alternatives (anyOf)."},"schema/block/annotation":{"name":"Annotation","summary":"An inline text annotation (bold, link, …) over character ranges, plus arbitrary inline attributes."},"schema/block/base":{"name":"Block (Base)","summary":"Fields shared by every concrete block type: id, optional revision, and the type discriminator. Concrete blocks extend this."},"schema/block/button-alignment":{"name":"Button Alignment","summary":"Horizontal alignment of a Button block."},"schema/block/button":{"name":"Button Block","summary":"A labelled button linking somewhere."},"schema/block/children-type":{"name":"Children Type","summary":"How a block's children are laid out: Group (default), Ordered, Unordered, Blockquote, or Grid."},"schema/block/code":{"name":"Code Block","summary":"A code block, optionally tagged with a language."},"schema/block/comment":{"name":"Comment Block","summary":"A comment content block: a Block extended with a recursive list of child comment blocks."},"schema/block/core":{"name":"Core Block","summary":"The union of the fifteen built-in block types (Paragraph, Heading, Code, Math, Image, Video, File, Button, Embed, WebEmbed, Nostr, Table, TableRow, TableColumn,"},"schema/block/embed-view":{"name":"Embed View","summary":"How an Embed block renders its target: Content, Card, Comments, or Link."},"schema/block/embed":{"name":"Embed Block","summary":"An embed of another Hypermedia document (an hm:// URL)."},"schema/block/file":{"name":"File Block","summary":"A file attachment, referenced by a URL."},"schema/block/heading":{"name":"Heading Block","summary":"A section heading."},"schema/block/image":{"name":"Image Block","summary":"An image, referenced by a URL (typically ipfs://)."},"schema/block/math":{"name":"Math Block","summary":"A block of LaTeX/KaTeX math."},"schema/block/node":{"name":"Block Node","summary":"A node of the document content tree: a Block plus its ordered child Block nodes. The recursion (children of the same type) expresses arbitrary nesting; a leaf s"},"schema/block/nostr":{"name":"Nostr Block","summary":"An embed of a Nostr event (a nostr: URL)."},"schema/block/paragraph":{"name":"Paragraph Block","summary":"A paragraph of rich text with annotations."},"schema/block/query":{"name":"Query Block","summary":"A block that embeds a live query: its results (documents from the queried spaces) render in place, styled as cards, a list, or a table."},"schema/block/table-column":{"name":"Table Column Block","summary":"One column of a Table block: childless, identified by its block id (cells reference it via their columnId attribute), ordered by sibling position."},"schema/block/table-row":{"name":"Table Row Block","summary":"One row of a Table block. Its children are Paragraph cell blocks, each carrying a columnId attribute referencing a TableColumn id."},"schema/block/table":{"name":"Table Block","summary":"A table container. Its children are TableColumn blocks (childless; their sibling order defines column display order) followed by TableRow blocks whose children "},"schema/block/video":{"name":"Video Block","summary":"A video, referenced by a URL."},"schema/block/web-embed":{"name":"Web Embed Block","summary":"An embed of an external web resource (an http(s) URL)."},"schema/boolean":{"name":"Boolean","summary":"A true or false value."},"schema/bytes":{"name":"Bytes","summary":"Raw binary data (a byte string)."},"schema/change-body":{"name":"Change Body","summary":"The operations payload of a Change: an operation count hint and the list of ops."},"schema/contact-subscribe":{"name":"Contact Subscription","summary":"Subscription preferences for a contact: subscribe to the subject's site and/or profile."},"schema/date-time":{"name":"Date-Time","summary":"An instant as an RFC 3339 / ISO 8601 string, `YYYY-MM-DDTHH:MM:SS[.sss]Z` or with a numeric offset (e.g. `2026-08-26T14:30:00Z`). A refinement of string with `f"},"schema/date":{"name":"Date","summary":"A calendar date as an ISO 8601 string, `YYYY-MM-DD` (e.g. `2026-08-26`). A refinement of string — the value is still plain text on the wire — with `format: date"},"schema/float":{"name":"Float","summary":"A floating-point number."},"schema/include-schema":{"name":"Reference schema","summary":"The variant for a reference: a bare include, or an extension when it carries refinements."},"schema/integer":{"name":"Integer","summary":"A whole number. DAG-CBOR encodes integers distinctly from floats."},"schema/key-value":{"name":"Key/Value","summary":"A metadata attribute: a dotted key path (segments) and a value."},"schema/link-schema":{"name":"Link schema","summary":"The variant for a link (CID), optionally naming the expected target type."},"schema/link":{"name":"Link","summary":"A content-addressed pointer (CID) to another block."},"schema/list-schema":{"name":"List schema","summary":"The variant for a list value; items types the elements."},"schema/list":{"name":"List","summary":"An ordered sequence — List<Any> until parameterized with items."},"schema/literal-schema":{"name":"Literal Schema","summary":"The variant for a literal — a schema that accepts exactly one value, with a description of what that value means."},"schema/map-schema":{"name":"Map schema","summary":"The variant for a map — arbitrary keys whose values all match one schema (values). Known fields belong to a struct schema."},"schema/map":{"name":"Map","summary":"A map of string keys to values of one type — Map<Any> until constrained by values. For known, named fields use a struct."},"schema/navigation-item":{"name":"Navigation item","summary":"One entry of a site's navigation menu, stored in document metadata: a link with display text."},"schema/null":{"name":"Null","summary":"The null value."},"schema/op":{"name":"Operation","summary":"A single CRDT operation inside a Change body — a discriminated union tagged on type."},"schema/op/delete-blocks":{"name":"DeleteBlocks Op","summary":"Delete blocks by id."},"schema/op/move-blocks":{"name":"MoveBlocks Op","summary":"Move blocks under a parent, using RGA CRDT reference ids."},"schema/op/replace-block":{"name":"ReplaceBlock Op","summary":"Replace the content of a block."},"schema/op/set-attributes":{"name":"SetAttributes Op","summary":"Set attributes on a block, or document-level metadata when block is empty."},"schema/op/set-key":{"name":"SetKey Op","summary":"Deprecated: set a single flat metadata key to a value."},"schema/property":{"name":"Property","summary":"One field of a struct — its value schema, whether a value must include it, and a description of what it is for."},"schema/query":{"name":"Query","summary":"A live document query: which spaces/paths to include, how to sort, and an optional result limit. Embedded in a Query block's attributes; also the input of the Q"},"schema/query/inclusion":{"name":"Query Inclusion","summary":"One source a Query block pulls documents from: a space (account), an optional path prefix inside it, and whether to list direct Children or AllDescendants."},"schema/query/sort":{"name":"Query Sort","summary":"One sort term for a Query block's results, optionally reversed."},"schema/query/style":{"name":"Query Style","summary":"How a Query block presents its results: a card grid, a compact list, or a table."},"schema/query/table-config":{"name":"Query Table Config","summary":"Persisted presentation settings for a Query block's Table view: which columns are visible and how wide they are."},"schema/redirect-target":{"name":"Redirect Target","summary":"A redirect from one document to another space and/or path."},"schema/scalar-schema":{"name":"Scalar schema","summary":"The variant for a scalar value (null, boolean, integer, float, string, bytes), optionally narrowed by value constraints. To pin a scalar to one value, use a literal."},"schema/string":{"name":"String","summary":"UTF-8 text."},"schema/struct-schema":{"name":"Struct schema","summary":"The variant for a struct — known fields via properties and required, optionally open to extra keys via values."},"schema/struct":{"name":"Struct","summary":"A map with known, named fields — the type behind every record-like value, from an address to a signed Change."},"schema/timestamp":{"name":"Timestamp","summary":"A timestamp, encoded as an integer of Unix milliseconds."},"schema/value":{"name":"Value","summary":"A metadata / attribute value: string, integer, boolean, or null."},"schema/var-schema":{"name":"Variable Schema","summary":"A type-variable reference: matches whatever a generic's parameter is bound to. Written { \"var\": \"<name>\" }."},"signature":{"name":"Signature","summary":"A cryptographic signature over the blob — raw CBOR bytes."},"url":{"name":"URL","summary":"A string holding a URL of any scheme — `https://…`, `hm://…`, `ipfs://…`. `format: url` tells an editor to render it as a link and to validate the shape, not a plain text field."},"visibility":{"name":"Visibility","summary":"'Resource visibility: \"\" (empty) for public, \"Private\" for private.'"}}

